// Rasterises scripts/og.svg into public/og.png.
//
// The SVG is generated by scripts/build-og.py, which converts every string to
// outlines using the site's real fonts — so this step needs no fonts installed
// and produces the same card on any machine. Run both with `npm run og`.
import sharp from 'sharp';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const src = resolve(here, 'og.svg');
const out = resolve(here, '../public/og.png');

const svg = readFileSync(src);

await sharp(svg, { density: 144 })
  .resize(1200, 630)
  .png({ compressionLevel: 9 })
  .toFile(out);

console.log(`  wrote ${out}`);
